-- ONC-OSI-INC-01 (inclusion): 病患年齡須滿十八歲。
c_onc_osi_inc_01 AS (
  SELECT b.pid, b.index_date, (((year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) >= 18)) AS v,
